_print_lock = threading.Lock()


def say(field, msg):
    with _print_lock:
        for line in str(msg).splitlines() or ['']:
            print(('[%s] ' % field if field else '') + line, flush=True)


# ------------------------------------------------------------------ small utils
def sha256_file(path, bufsize=1 << 20):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            b = f.read(bufsize)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def fits_data_sha256(path):
    """sha256 over the data units of all HDUs (headers ignored) -- pure python FITS walk."""
    try:
        outer = hashlib.sha256()
        with open(path, 'rb') as f:
            nh = 0
            while True:
                cards = {}
                got_end = False
                first = True
                while not got_end:
                    blk = f.read(2880)
                    if len(blk) < 2880:
                        if first:
                            return outer.hexdigest() if nh else None
                        return None
                    first = False
                    for i in range(0, 2880, 80):
                        c = blk[i:i + 80].decode('ascii', 'replace')
                        k = c[:8].strip()
                        if k == 'END':
                            got_end = True
                            break
                        if c[8:10] == '= ':
                            v = c[10:].split('/')[0].strip()
                            cards[k] = v
                nh += 1
                bitpix = int(cards.get('BITPIX', '8'))
                naxis = int(cards.get('NAXIS', '0'))
                n = 1
                for i in range(1, naxis + 1):
                    n *= int(cards.get('NAXIS%d' % i, '0'))
                if naxis == 0:
                    n = 0
                pc = int(cards.get('PCOUNT', '0'))
                gc = int(cards.get('GCOUNT', '1'))
                size = abs(bitpix) // 8 * gc * (pc + n)
                hh = hashlib.sha256()
                left = size
                while left > 0:
                    b = f.read(min(left, 1 << 22))
                    if not b:
                        break
                    hh.update(b)
                    left -= len(b)
                pad = (-size) % 2880
                f.read(pad)
                outer.update(hh.digest())
    except Exception:
        return None


def tcl_crc(text):
    return zlib.crc32(text.encode('utf-8')) & 0xFFFFFFFF


def strip_one_nl(s):
    return s[:-1] if s.endswith('\n') else s


def read_text(p):
    with open(p, 'r', encoding='utf-8', newline='') as f:
        return f.read()


def write_text(p, s):
    os.makedirs(os.path.dirname(p) or '.', exist_ok=True)
    tmp = p + '.tmp'
    with open(tmp, 'w', encoding='utf-8', newline='') as f:
        f.write(s)
    os.replace(tmp, p)


def sanitize(name):
    return re.sub(r'[^A-Za-z0-9_]', '_', name)


def parse_kv(s, sep='='):
    i = s.find(sep)
    if i <= 0:
        raise argparse.ArgumentTypeError("expected NAME%sVALUE, got %r" % (sep, s))
    return s[:i], s[i + 1:]


# ------------------------------------------------------------------ environment
def lib_env():
    env = dict(os.environ)
    var = 'DYLD_LIBRARY_PATH' if platform.system() == 'Darwin' else 'LD_LIBRARY_PATH'
    libpaths = []
    if os.environ.get('CONDA_PREFIX'):
        libpaths.append(os.path.join(os.environ['CONDA_PREFIX'], 'lib'))
    hc = os.path.join(os.path.expanduser('~'), 'miniconda3', 'lib')
    if os.path.isdir(hc):
        libpaths.append(hc)
    if os.environ.get(var):
        libpaths.append(os.environ[var])
    if libpaths:
        env[var] = ':'.join(libpaths)
    # Moving Objects steps need the ASSIST ephemeris files (~/.ds9/ephem of the GUI machine): when the script runs with another
    # HOME, fall back to the directory recorded in the session
    ed = SESSION_META.get('ephem_dir')
    if ed and 'OGF_EPHEM_DIR' not in env and not os.path.isdir(os.path.join(os.path.expanduser('~'), '.ds9', 'ephem')) and os.path.isdir(ed):
        env['OGF_EPHEM_DIR'] = ed
    return env


def sextract_info(root, path):
    sb = os.path.join(root, 'ogfmeas', 'sextract.py')
    d = {}
    if not os.path.isfile(sb) or not os.path.exists(path):
        return d
    try:
        out = subprocess.run([sys.executable, sb, '--info', path], capture_output=True, text=True, env=lib_env(), timeout=120).stdout
    except Exception:
        return d
    for line in out.splitlines():
        m = re.match(r'^([A-Z0-9_]+)=(.*)$', line)
        if m:
            d[m.group(1)] = m.group(2).strip()
    return d


# ------------------------------------------------------------------ field object
class StepFail(Exception):
    pass


class Field:
    def __init__(self, name, images, args, cfg):
        self.name = name
        self.images = dict(images)           # key -> path (user supplied names)
        self.args = args
        self.cfg = cfg or {}
        self.root = args.ogfinder_root
        self.dir = os.path.abspath(os.path.join(args.outdir, name))
        self.work = os.path.join(self.dir, 'work')
        self.out = os.path.join(self.dir, 'outputs')
        self.stepdir = os.path.join(self.dir, '.steps')
        self.logfile = os.path.join(self.dir, 'session.log')
        self.state = {'stars': [], 'psf': False}
        self.registry = {}                   # band name -> dict(file,zp,fwhm,pscale,pivot)
        self.reg_order = []
        self.detect = None
        self.records = []
        self.mask_stats = {}
        self.info = {}
        self.t_start = time.time()
        self.replay = (args.mode == 'replay')
        self.det_key_rec = SESSION_META.get('detection_key') or ''
        self.det_path = None
        self._logfh = None

    # ---- logging
    def log(self, msg):
        say(self.name, msg)
        if self._logfh:
            self._logfh.write(str(msg) + '\n')
            self._logfh.flush()

    # ---- image roles
    def img_for(self, key):
        if key == self.det_key_rec and self.det_path:
            return self.det_path
        return self.images.get(key)

    def info_for(self, path):
        if path not in self.info:
            self.info[path] = sextract_info(self.root, path)
        return self.info[path]

    def cat_path(self):
        return os.path.join(self.work, 'catalog_state.tsv')

    def get_cat(self):
        p = self.cat_path()
        return read_text(p) if os.path.exists(p) else ''

    def set_cat(self, text):
        write_text(self.cat_path(), text)

    # ---- per-band resolution (zp, pixel scale, fwhm)
    def resolve_numbers(self, key):
        """returns dict zp,pscale for the image of a recorded key (strings)"""
        a = self.args
        path = self.img_for(key)
        info = self.info_for(path) if path else {}
        bname = self.band_name_of(path)
        out = {}
        for what, hdr, cli in (('zp', 'ZP_AB', a.zp_map), ('pscale', 'PIXSCALE', a.pixel_scale_map)):
            v = None
            for k in (bname, key, '*'):
                if k and k in cli:
                    v = cli[k]
                    break
            if v is None and (self.cfg.get(what) or {}):
                c = self.cfg[what]
                for k in (bname, key, '*'):
                    if k in c:
                        v = str(c[k])
                        break
            if v is None and not self.replay and hdr in info and info[hdr] not in ('', 'nan'):
                v = info[hdr]
            out[what] = v
        return out

    def band_name_of(self, path):
        for n, b in self.registry.items():
            if b['file'] == path:
                return n
        for k, p in self.images.items():
            if p == path:
                return k
        return None


# ------------------------------------------------------------------ catalog helper
def catalog_tool(field, *argv):
    cmd = [sys.executable, os.path.join(field.root, 'ds9', 'library', 'ds9_catalog_edit.py')] + list(argv)
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.stderr.strip():
        field.log('  ' + r.stderr.strip().replace('\n', '\n  '))
    if r.returncode != 0:
        raise StepFail('ds9_catalog_edit %s failed (rc=%d): %s' % (argv[0], r.returncode, r.stderr.strip()[-300:]))
    return r.stdout


# ------------------------------------------------------------------ token expansion
_tok = re.compile(r'@\{([^}]*)\}')


def expand(field, token, cat_written):
    def rep(m):
        t = m.group(1)
        if t == 'PY':
            return field.args.python
        if t == 'SEXTRACT':
            return os.path.join(field.root, 'ogfmeas', 'sextract.py')
        if t == 'LIB':
            return os.path.join(field.root, 'ds9', 'library')
        if t == 'ROOT':
            return field.root
        if t == 'WORK':
            return field.work
        if t == 'OUT':
            return field.out
        if t.startswith('CAT:') or t.startswith('CATNL:'):
            nm = t.split(':', 1)[1]
            p = os.path.join(field.work, nm + '_catalog.tsv')
            cat_written[p] = t.startswith('CATNL')
            return p
        if t.startswith('IMG:'):
            p = field.img_for(t[4:])
            if p is None:
                raise KeyError('image ' + t[4:])
            return p
        if t.startswith('BASE:'):
            p = field.img_for(t[5:])
            if p is None:
                raise KeyError('image ' + t[5:])
            b = os.path.basename(p)
            if b.endswith('.gz'):
                b = b[:-3]
            return os.path.splitext(b)[0]
        raise KeyError(t)
    return _tok.sub(rep, token)


def files_span(argv_t):
    """(start, end) token range of the exposures after `--files` (Moving Objects steps), or None."""
    if '--files' not in argv_t:
        return None
    i = argv_t.index('--files') + 1
    j = i
    while j < len(argv_t) and not argv_t[j].startswith('--'):
        j += 1
    return (i, j) if j > i else None


def field_files(field):
    """exposures of a multi-exposure step (Moving Objects): replay = the recorded exposures in recorded order,
    pipeline = every image supplied for the field in the order given."""
    if field.replay:
        order = {i['key']: n for n, i in enumerate(IMAGES)}
        keys = sorted(field.images, key=lambda k: order.get(k, 1 << 20))
    else:
        keys = list(field.images)
    return [field.images[k] for k in keys]


def step_image_keys(rec, with_files=True):
    keys = []
    sp = files_span(rec['argv_t'])
    toks = rec['argv_t'] if (with_files or not sp) else rec['argv_t'][:sp[0]] + rec['argv_t'][sp[1]:]
    for t in toks:
        for m in re.finditer(r'@\{IMG:([^}]*)\}', t):
            if m.group(1) not in keys:
                keys.append(m.group(1))
    for t in toks:
        for m in re.finditer(r'@\{BASE:([^}]*)\}', t):
            if m.group(1) not in keys:
                keys.append(m.group(1))
    return keys


def set_flag(argv, flag, value):
    if flag in argv:
        i = argv.index(flag)
        if i + 1 < len(argv):
            argv[i + 1] = value
            return
    argv.extend([flag, value])


# ------------------------------------------------------------------ running one tool
def snapshot_dir(root):
    snap = {}
    for dp, dn, fn in os.walk(root):
        dn[:] = [d for d in dn if d != '.steps']
        for f in fn:
            p = os.path.join(dp, f)
            try:
                st = os.stat(p)
            except OSError:
                continue
            snap[p] = (st.st_size, st.st_mtime_ns)
    return snap


def run_tool(field, rec, argv, label):
    field.log('  $ ' + ' '.join(shlex_quote(a) for a in argv))
    t0 = time.time()
    p = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=lib_env())
    dt = time.time() - t0
    out = p.stdout.decode('utf-8', 'replace')
    err = p.stderr.decode('utf-8', 'replace')
    with open(os.path.join(field.dir, 'tool_stderr.log'), 'a', encoding='utf-8') as f:
        f.write('===== step %s %s\n%s\n' % (rec['seq'], rec['step'], err))
    tail = err.strip().splitlines()[-3:]
    for l in tail:
        field.log('    | ' + l[:200])
    if p.returncode != 0:
        raise StepFail('%s exited with status %d: %s' % (os.path.basename(argv[1] if len(argv) > 1 else argv[0]),
                                                        p.returncode, (tail[-1] if tail else '')[:200]))
    return out, dt


def shlex_quote(s):
    if re.match(r'^[A-Za-z0-9_@%+=:,./-]+$', s):
        return s
    return "'" + s.replace("'", "'\"'\"'") + "'"


def post_process(field, rec, out):
    post = rec.get('post') or {}
    kind = post.get('kind', '')
    res = strip_one_nl(out)
    tmp = os.path.join(field.work, 'last_result.tsv')
    if kind in ('set', 'add', 'star', 'morph', 'ai'):
        write_text(tmp, res)
    if kind == 'set':
        extra = ['--force'] if post.get('force') else []
        if not field.get_cat() and False:
            pass
        r = catalog_tool(field, 'set', '--catalog', field.cat_path(), '--input', tmp, *extra)
        if rec['step'] == 'extract' and os.path.exists(field.cat_path()):
            shutil.copyfile(field.cat_path(), os.path.join(field.work, 'extract_catalog.tsv'))
        field.log('  catalog: ' + r.strip())
    elif kind == 'add':
        if not field.get_cat():
            raise StepFail('no catalog to add columns to')
        cols = ','.join(post.get('cols', []))
        r = catalog_tool(field, 'add-columns', '--catalog', field.cat_path(), '--result', tmp, '--columns', cols)
        field.log('  catalog: ' + r.strip())
    elif kind == 'ai':
        # external AI service columns (ai.run): new columns first, then the ones that already exist
        # (CatalogPanelAddColumnsFromTSV skips new columns when any requested one exists)
        if not field.get_cat():
            raise StepFail('no catalog to add columns to')
        have = field.get_cat().split('\n')[0].split('\t')
        cols = list(post.get('cols', []))
        for grp in ([c for c in cols if c not in have], [c for c in cols if c in have]):
            if grp:
                r = catalog_tool(field, 'add-columns', '--catalog', field.cat_path(), '--result', tmp, '--columns', ','.join(grp))
                field.log('  catalog: ' + r.strip())
    elif kind == 'star':
        r = catalog_tool(field, 'add-columns', '--catalog', field.cat_path(), '--result', tmp,
                         '--columns', 'AI_STAR,AI_STAR_CONF', '--strip-comments')
        field.log('  catalog: ' + r.strip())
    elif kind == 'morph':
        r = catalog_tool(field, 'morph-columns', '--catalog', field.cat_path(), '--result', tmp)
        field.log('  catalog: ' + r.strip())
    elif kind == 'stars':
        stars = []
        for line in out.split('\n'):
            if line.startswith('#PSF_STARS') or line.startswith('NUMBER') or not line:
                continue
            f = line.split('\t')
            if len(f) >= 3:
                stars.append(f[0])
        field.state['stars'] = stars
        field.log('  %d PSF stars found' % len(stars))
    for line in out.splitlines():
        if line.startswith('#MASK_STATS'):
            field.mask_stats = dict(kv.split('=', 1) for kv in line.split()[1:] if '=' in kv)
            field.log('  ' + line)
    if kind == 'psfbuilt':
        field.state['psf'] = True


# ------------------------------------------------------------------ native steps
def band_sorted(field):
    names = list(field.reg_order)
    if all(field.registry[n].get('pivot') not in (None, '') for n in names):
        return [n for n, _ in sorted(((n, float(field.registry[n]['pivot'])) for n in names), key=lambda t: t[1])]
    return names


def native_bands_measure(field, rec):
    pl = rec['payload']
    snr = pl.get('snr', '2.0')
    names = band_sorted(field)
    if len(names) < 2 and not field.replay:
        return 'skip', 'only %d band registered -- multi-band forced photometry needs >= 2 bands' % len(names)
    if not field.get_cat():
        return 'skip', 'no catalog (run extraction first)'
    det = field.detect
    detfile = field.registry[det]['file']
    catfile = os.path.join(field.work, 'bands_catalog.tsv')
    write_text(catfile, field.get_cat())
    script = os.path.join(field.root, 'ogfmeas', 'sextract.py')
    for b in names:
        argv = [field.args.python, script, detfile, '--forced-catalog', catfile, '--measure-image', field.registry[b]['file'],
                '--band', b, '--mag-zeropoint', str(field.registry[b]['zp']), '--snr-min', str(snr)]
        out, dt = run_tool(field, rec, argv, b)
        raw = os.path.join(field.work, 'forced_%s.raw' % b)
        ren = os.path.join(field.work, 'forced_%s.tsv' % b)
        write_text(raw, out)
        catalog_tool(field, 'forced-rename', '--input', raw, '--band', b, '--output', ren)
        r = catalog_tool(field, 'add-columns', '--catalog', field.cat_path(), '--result', ren,
                         '--columns', 'MAG_%s,MAGERR_%s' % (b, b))
        field.log('  band %s: %s (%.1f s)' % (b, r.strip(), dt))
    r = catalog_tool(field, 'band-colors', '--catalog', field.cat_path(), '--order', ','.join(names))
    field.log('  colours: ' + r.strip())
    return 'ok', ''


def native_mask_copy(field, rec):
    names = band_sorted(field)
    if len(names) < 2 and not field.replay:
        return 'skip', 'only %d band registered -- nothing to copy the mask to' % len(names)
    det = field.detect
    detfile = field.registry[det]['file']

    def mpath(f):
        b = os.path.basename(f)
        b = b[:-3] if b.endswith('.gz') else b
        return os.path.join(field.work, 'mask_%s.fits' % os.path.splitext(b)[0])
    dm = mpath(detfile)
    if not os.path.exists(dm):
        return 'skip', 'no mask on the detection band (%s)' % det
    script = os.path.join(field.root, 'ds9', 'library', 'ds9_mask.py')
    for b in field.reg_order:
        if b == det:
            continue
        bf = field.registry[b]['file']
        argv = [field.args.python, script, detfile, '--mode', 'reproject', '--mask', dm,
                '--target-image', bf, '--output', mpath(bf)]
        out, dt = run_tool(field, rec, argv, b)
        for line in out.splitlines():
            if line.startswith('#MASK_STATS'):
                field.log('  [%s] %s' % (b, line))
    return 'ok', ''


def write_edit_json(field, ops):
    p = os.path.join(field.work, 'edit_%s.json' % field.state.get('_seq', 0))
    with open(p, 'w') as f:
        json.dump({'ops': ops}, f)
    return p


def native_catalog_edit(field, rec):
    st = rec['step']
    pl = rec['payload']
    if not field.get_cat() and st != 'catalog.clear' and st != 'catalog.load':
        return 'skip', 'no catalog'
    if st == 'catalog.trim':
        conds = pl.get('conditions', [])
        if field.args.trim_map and not field.replay:
            conds = [dict(col=c, **({'min': lo} if lo != '' else {}), **({'max': hi} if hi != '' else {}))
                     for c, (lo, hi) in field.args.trim_map.items()]
            field.log('  trim limits overridden on the command line: %s' % field.args.trim)
        elif not field.replay:
            field.log('  trim uses the limits recorded in the GUI session (%s); override with --trim COL=MIN:MAX'
                      % ', '.join('%s %s..%s' % (c['col'], c.get('min', ''), c.get('max', '')) for c in conds))
        ops = [{'op': 'trim', 'conditions': conds}]
    elif st == 'catalog.sort':
        ops = [{'op': 'sort', 'col': pl['col'], 'dir': pl['dir']}]
    elif st == 'catalog.merge':
        ops = [{'op': 'merge', 'nums': pl['nums'], 'mag_zp': pl.get('mag_zp', '25.0')}]
    elif st == 'catalog.delete':
        ops = [{'op': 'delete', 'number': pl['number']}]
    else:
        raise StepFail('unknown catalog step ' + st)
    ej = write_edit_json(field, ops)
    extra = [] if field.replay else ['--lenient']
    r = catalog_tool(field, 'apply', '--catalog', field.cat_path(), '--edits', ej, *extra)
    field.log('  catalog: ' + r.strip())
    return 'ok', ''


def native_catalog_clear(field, rec):
    p = field.cat_path()
    if os.path.exists(p):
        os.remove(p)
    return 'ok', ''


def native_catalog_load(field, rec):
    f = rec['payload'].get('file', '')
    if not os.path.exists(f):
        return 'skip', 'catalog file %s from the GUI session does not exist here' % f
    raw = read_text(f).rstrip('\n')
    if f.lower().endswith('.csv'):
        return 'skip', 'CSV catalog load is not replayed'
    tmp = os.path.join(field.work, 'loaded_catalog.raw')
    write_text(tmp, raw)
    catalog_tool(field, 'set', '--catalog', field.cat_path(), '--input', tmp)
    return 'ok', ''


def native_catalog_save(field, rec):
    cat = field.get_cat()
    if not cat:
        return 'skip', 'no catalog to save'
    name = rec['payload'].get('name', 'catalog.tsv')
    dest = os.path.join(field.out, name)
    if name.lower().endswith('.csv'):
        csvdata = []
        for line in cat.split('\n'):
            if line.strip() == '':
                continue
            flds = []
            for fld in line.split('\t'):
                fld = fld.strip()
                if ',' in fld or '"' in fld:
                    fld = '"' + fld.replace('"', '""') + '"'
                flds.append(fld)
            csvdata.append(','.join(flds))
        write_text(dest, '\n'.join(csvdata))
    else:
        write_text(dest, cat)
    field.log('  saved catalog -> ' + dest)
    mp = os.path.join(field.work, 'catalog_meta.json')       # catalog metadata of the plugins (see ogfkit/meta.py), as in the GUI's Save Catalog
    if os.path.exists(mp):
        try:
            if int(json.load(open(mp)).get('nrows', -1)) == len([l for l in cat.split('\n') if l.strip()]) - 1:
                shutil.copyfile(mp, dest + '.meta.json')
                field.log('  catalog metadata -> ' + dest + '.meta.json')
        except Exception:
            pass
    return 'ok', ''


def native_psf_load(field, rec):
    f = rec['payload'].get('file', '')
    if not os.path.exists(f):
        return 'skip', 'PSF file %s from the GUI session does not exist here' % f
    shutil.copyfile(f, os.path.join(field.work, 'psf_current.fits'))
    field.state['psf'] = True
    return 'ok', ''


def native_regs(field, rec):
    return 'ok', ''


NATIVE = {
    'bands.measure': native_bands_measure,
    'mask.copy_to_bands': native_mask_copy,
    'catalog.trim': native_catalog_edit,
    'catalog.sort': native_catalog_edit,
    'catalog.merge': native_catalog_edit,
    'catalog.delete': native_catalog_edit,
    'catalog.clear': native_catalog_clear,
    'catalog.load': native_catalog_load,
    'catalog.save': native_catalog_save,
    'psf.load': native_psf_load,
}


# ------------------------------------------------------------------ band registry
def init_registry(field):
    """Pipeline mode: registry from the supplied images (header values, CLI overrides, recorded
    defaults).  Replay mode: starts empty and is filled by the recorded bands.register steps."""
    a = field.args
    if field.replay:
        return
    keys = list(field.images.keys())
    det = field.cfg.get('detection_band') or a.detection_band
    if det and det not in field.images:
        # allow the detection image to be given by role
        pass
    if not det:
        det = field.det_key_rec if field.det_key_rec in field.images else (keys[0] if keys else None)
    field.detect = det
    field.det_path = field.images.get(det) if det else None
    rec_reg = {}
    for rec in STEPS:
        if rec['step'] == 'bands.register':
            rec_reg[rec['payload']['name']] = rec['payload']
    for k in keys:
        p = field.images[k]
        info = field.info_for(p)
        nums = field.resolve_numbers(k)
        # recorded default (same band name or the session's extraction zeropoint)
        zp = nums['zp']
        if zp is None:
            zp = rec_reg.get(k, {}).get('zp') or '25.0'
        field.registry[k] = {'file': p, 'zp': zp, 'fwhm': (a.fwhm_map.get(k) or (field.cfg.get('fwhm') or {}).get(k)
                                                            or rec_reg.get(k, {}).get('fwhm', '')),
                             'pscale': nums['pscale'] or info.get('PIXSCALE', ''), 'pivot': info.get('PIVOT', '')}
        field.reg_order.append(k)


def apply_config_step(field, rec):
    """replay-mode registry events"""
    st = rec['step']
    pl = rec['payload']
    if st == 'bands.register':
        name = pl['name']
        path = field.images.get(name) or field.images.get(pl.get('key', '')) or None
        if path is None:
            path = field.img_for(name)
        if path is None:
            raise StepFail('no input image for band %s' % name)
        info = field.info_for(path)
        if name not in field.reg_order:
            field.reg_order.append(name)
        field.registry[name] = {'file': path, 'zp': pl['zp'], 'fwhm': pl.get('fwhm', ''),
                                'pscale': info.get('PIXSCALE', ''), 'pivot': info.get('PIVOT', '')}
        if field.detect is None:
            field.detect = name
    elif st == 'bands.detect':
        field.detect = pl['name']
    elif st == 'bands.remove':
        n = pl['name']
        if n in field.reg_order:
            field.reg_order.remove(n)
            field.registry.pop(n, None)
            if field.detect == n:
                field.detect = field.reg_order[0] if field.reg_order else None


# ------------------------------------------------------------------ one step
def decide(field, rec):
    """returns (action, reason): action in run|skip"""
    a = field.args
    cls = rec['class']
    if int(rec.get('failed') or 0):
        return 'skip', 'failed in the GUI session (%s)' % rec.get('note', '')
    if cls == 'note':
        return 'skip', 'informational record, nothing to run: %s' % (rec.get('note') or rec['title'])
    if cls == 'config':
        return ('run' if field.replay else 'skip'), ('' if field.replay else
                                                      'band registry is built from the input list in pipeline mode')
    if cls == 'manual' and not (field.replay or a.include_manual):
        return 'skip', 'MANUAL step (done by hand in the GUI): %s -- use --include-manual or --mode replay to replay it' % rec['title']
    if rec['step'] in ('catalog.unrecorded', 'catalog.separate', 'catalog.add_object'):
        return 'skip', ('WARNING: MANUAL catalog edit that cannot be replayed from the shell (%s); results from here '
                        'on differ from the GUI session' % rec['title'])
    return 'run', ''


def check_requirements(field, rec):
    """returns reason string if a requirement is not met"""
    for key in step_image_keys(rec, with_files=field.replay):
        if field.img_for(key) is None:
            return 'input image/band %r of the recorded session is not available in this field' % key
    if files_span(rec['argv_t']) and not field_files(field):
        return 'no exposures supplied for this field'
    for r in rec.get('requires') or []:
        if r == 'catalog' and not field.get_cat():
            return 'no catalog available'
        if r == 'psf' and not os.path.exists(os.path.join(field.work, 'psf_current.fits')):
            return 'no PSF available (PSF build step did not run)'
        if r == 'stars' and not field.state['stars']:
            return 'no PSF stars (star finder did not run / found none)'
        if r.startswith('cols:'):
            have = field.get_cat().split('\n')[0].split('\t') if field.get_cat() else []
            miss = [c for c in r[5:].split(',') if c and c not in have]
            if miss:
                return 'catalog lacks required column(s) %s' % ','.join(miss)
        if r == 'bands>=2' and len(field.reg_order) < 2:
            return 'needs at least two bands'
        if r == 'extract_catalog' and not os.path.exists(os.path.join(field.work, 'extract_catalog.tsv')):
            return 'no extraction catalogue (extraction step did not run)'
    if any('@{CAT' in t for t in rec['argv_t']) and not field.get_cat():
        return 'no catalog available (extraction did not produce one)'
    for tok in rec.get('winputs') or []:
        try:
            p = expand(field, tok, {})
        except KeyError:
            continue
        if not os.path.exists(p):
            return 'intermediate input %s was not produced (the step that creates it did not run)' % os.path.relpath(
                p, field.dir)
    if rec['step'] == 'ai.run' and (rec.get('payload') or {}).get('transport') == 'agent_cli':
        # an agent CLI forwards the catalogue rows to its provider's cloud model: needs its own switch in pipeline mode
        if not (field.replay or getattr(field.args, 'allow_agent_cli', False)):
            return ('hands catalogue data to the agent CLI %s (cloud model); use --allow-agent-cli' %
                    (rec.get('payload') or {}).get('backend', ''))
        if str((rec.get('payload') or {}).get('send_images')) in ('1', 'true', 'True') and not (
                field.replay or getattr(field.args, 'allow_agent_images', False)):
            return 'sends image cutouts to the agent CLI (cloud model); use --allow-agent-images as well'
    elif rec.get('network') and str(rec.get('network')) not in ('0', '') and not (field.replay or field.args.allow_network):
        return 'needs network access (%s); use --allow-network' % ('external AI service' if rec['step'] == 'ai.run' else 'VizieR')
    return None


def build_argv(field, rec):
    cat_written = {}
    argv = []
    sp = files_span(rec['argv_t'])
    for n_, t in enumerate(rec['argv_t']):
        if sp and not field.replay and sp[0] <= n_ < sp[1]:
            if n_ == sp[0]:
                argv.extend(field_files(field))        # pipeline mode: every exposure supplied for this field
            continue
        argv.append(expand(field, t, cat_written))
    # catalogue temp files, written exactly as the GUI wrote them
    for p, nl in cat_written.items():
        txt = field.get_cat()
        write_text(p, txt + ('\n' if nl else ''))
    pl = rec.get('payload') or {}
    if 'regions_text' in pl:
        for i, t in enumerate(argv):
            if t.endswith('mask_regions.reg'):
                write_text(t, pl['regions_text'])
    if not field.replay:
        # image specific numbers: header / CLI / recorded
        keys = step_image_keys(rec)
        key = keys[0] if keys else field.det_key_rec
        nums = field.resolve_numbers(key) if field.img_for(key) else {}
        if nums.get('zp') and '--mag-zeropoint' in argv:
            set_flag(argv, '--mag-zeropoint', nums['zp'])
        elif '--mag-zeropoint' in argv and field.img_for(key):
            ck = '_zpwarn_%s' % key
            if ck not in field.state:
                field.state[ck] = 1
                field.log('  WARNING: no AB zeropoint in the FITS header of %s and none given with --zp; using the '
                          'value recorded in the GUI session (%s). Magnitudes are only meaningful if that is right.'
                          % (os.path.basename(field.img_for(key)), argv[argv.index('--mag-zeropoint') + 1]))
        if nums.get('pscale') and '--pixel-scale' in argv:
            set_flag(argv, '--pixel-scale', nums['pscale'])
        if '--center' in argv and not field.args.include_manual:
            ref = os.path.join(field.work, 'extract_catalog.tsv')
            if not os.path.exists(ref):
                raise StepFail('ICL centre: no extraction catalogue to pick the brightest source from')
            b = catalog_tool(field, 'brightest', '--catalog', ref).strip().split('\t')
            cx, cy = float(b[1]) - 1.0, float(b[2]) - 1.0
            set_flag(argv, '--center', '%s,%s' % (repr(cx), repr(cy)))
            field.log('  ICL centre (automatic): brightest source #%s at (%s, %s)' % (b[0], b[1], b[2]))
        if '--star-indices' in argv:
            if not field.state['stars']:
                raise StepFail('no PSF stars from the automatic star finder')
            set_flag(argv, '--star-indices', ','.join(field.state['stars']))
        if '--mag-zeropoint' in argv and rec['step'] == 'extract':
            pass
    for pat, flag, val in field.args.override_list + [tuple(x) for x in (field.cfg.get('overrides') or [])]:
        if fnmatch.fnmatch(rec['step'], pat):
            set_flag(argv, flag, val)
            field.log('  override: %s %s' % (flag, val))
    return argv


def run_native_or_tool(field, rec):
    st = rec['step']
    if st in NATIVE:
        return NATIVE[st](field, rec)
    argv = build_argv(field, rec)
    out, dt = run_tool(field, rec, argv, st)
    norm = out
    wd = SESSION_META.get('workdir')
    if wd:       # outputs live in ~/.ds9 in the GUI and in <outdir>/<field>/work here: compare modulo that prefix
        norm = norm.replace(field.work, wd).replace(field.out, wd)
    crc = tcl_crc(strip_one_nl(norm))
    rec['_crc'] = crc
    exp = rec.get('stdout_crc')
    if field.replay and exp not in (None, ''):
        rec['_crc_match'] = (str(crc) == str(exp))
        if not rec['_crc_match']:
            field.log('  WARNING: stdout of this step differs from the GUI session (crc %s vs %s)' % (crc, exp))
        else:
            field.log('  stdout identical to the GUI session (crc32 %08x, %s bytes)' % (crc, rec.get('stdout_len')))
    post_process(field, rec, out)
    return 'ok', ''


def step_key(field, rec, prev_chain):
    h = hashlib.sha256()
    h.update(prev_chain.encode())
    h.update(json.dumps({k: rec.get(k) for k in ('step', 'argv_t', 'payload', 'post', 'class')}, sort_keys=True).encode())
    h.update(json.dumps([field.args.mode, field.args.include_manual, field.args.python,
                         field.args.override_list, field.cfg], sort_keys=True, default=str).encode())
    for key in step_image_keys(rec):
        p = field.img_for(key)
        if p:
            h.update(file_digest_cached(p).encode())
    if files_span(rec['argv_t']):
        for p in field_files(field):
            h.update(file_digest_cached(p).encode())
    for k in sorted(field.registry):
        h.update(json.dumps([k, field.registry[k]], sort_keys=True).encode())
    return h.hexdigest()


_digest_cache = {}
_digest_lock = threading.Lock()


def file_digest_cached(p):
    st = os.stat(p)
    key = (p, st.st_size, st.st_mtime_ns)
    with _digest_lock:
        if key in _digest_cache:
            return _digest_cache[key]
    d = sha256_file(p)
    with _digest_lock:
        _digest_cache[key] = d
    return d


def clean_field_dir(field):
    for sub in ('work', 'outputs', '.steps'):
        shutil.rmtree(os.path.join(field.dir, sub), ignore_errors=True)
    for f in ('manifest.json', 'catalog_final.tsv', 'session.log', 'tool_stderr.log'):
        try:
            os.remove(os.path.join(field.dir, f))
        except OSError:
            pass


def run_field(field):
    a = field.args
    os.makedirs(field.dir, exist_ok=True)
    stored = {}
    sdir = field.stepdir
    resume_ok = bool(a.resume and os.path.isdir(sdir))
    if resume_ok:
        for f in glob.glob(os.path.join(sdir, '*.json')):
            try:
                d = json.load(open(f))
                stored[d['seq']] = d
            except Exception:
                pass
    if not resume_ok:
        clean_field_dir(field)
    for d in (field.work, field.out, field.stepdir):
        os.makedirs(d, exist_ok=True)
    field._logfh = open(field.logfile, 'a' if resume_ok else 'w', encoding='utf-8')
    field.log('=' * 78)
    field.log('field %s   mode=%s%s   outdir=%s' % (field.name, a.mode, '+manual' if a.include_manual else '', field.dir))
    for k, p in field.images.items():
        field.log('  image %-10s %s' % (k, p))
    status = 'ok'
    fail_step = ''
    fail_msg = ''
    chain = 'start'
    init_registry(field)
    rewound = False
    n = len(STEPS)
    counts = {'ran': 0, 'skipped': 0, 'cached': 0, 'failed': 0}
    for idx, rec0 in enumerate(STEPS):
        rec = copy.deepcopy(rec0)
        seq = int(rec['seq'])
        field.state['_seq'] = seq
        label = '%s (%s)' % (rec['step'], rec['class'])
        field.log('')
        field.log('===== [%s] step %d/%d  %s : %s =====' % (field.name, idx + 1, n, label, rec['title']))
        action, reason = decide(field, rec)
        if rec.get('note') and not int(rec.get('failed') or 0):
            field.log('  note: ' + rec['note'])
        entry = {'seq': seq, 'step': rec['step'], 'title': rec['title'], 'class': rec['class'],
                 'gui_ms': rec.get('ms')}
        if action == 'skip':
            if rec['class'] == 'config' and not field.replay:
                pass
            field.log('  SKIPPED: ' + reason)
            entry.update(status='skipped', reason=reason)
            counts['skipped'] += 1
            field.records.append(entry)
            continue
        if rec['class'] == 'config':
            apply_config_step(field, rec)
            entry.update(status='ok', note='registry updated')
            field.records.append(entry)
            continue
        miss = None
        try:
            miss = check_requirements(field, rec)
        except KeyError as e:
            miss = 'missing input %s' % e
        if miss:
            if field.replay:
                status, fail_step, fail_msg = 'failed', rec['step'], 'requirement not met in replay: ' + miss
                field.log('  FAILED: ' + fail_msg)
                entry.update(status='failed', reason=fail_msg)
                counts['failed'] += 1
                field.records.append(entry)
                break
            field.log('  SKIPPED: ' + miss)
            entry.update(status='skipped', reason=miss)
            counts['skipped'] += 1
            field.records.append(entry)
            continue
        key = step_key(field, rec, chain)
        sf = os.path.join(sdir, '%04d.json' % seq)
        prev = stored.get(seq)
        if resume_ok and not rewound and prev and prev.get('key') == key and prev.get('status') == 'ok' \
                and all(os.path.exists(os.path.join(field.dir, o['path'])) for o in prev.get('outputs', [])):
            # cached: restore the state the step left behind
            cs = os.path.join(sdir, '%04d.catalog.tsv' % seq)
            if os.path.exists(cs):
                shutil.copyfile(cs, field.cat_path())
            elif os.path.exists(field.cat_path()):
                os.remove(field.cat_path())
            field.state.update(prev.get('state', {}))
            field.mask_stats = prev.get('mask_stats', field.mask_stats)
            if rec['step'] in ('bands.measure',) or True:
                pass
            chain = key
            field.log('  CACHED (inputs and parameters unchanged, outputs present) -- not re-run')
            entry.update(status='cached', seconds=prev.get('seconds'), outputs=prev.get('outputs', []))
            counts['cached'] += 1
            field.records.append(entry)
            continue
        if resume_ok and not rewound and any(s > seq for s in stored):
            # the step (or something before it) changed but later results exist: steps modify
            # masks/catalogues in place, so earlier state cannot be trusted -> start this field over.
            field.log('  --resume: step %d changed after later steps had completed; the steps edit files in '
                      'place, so this field is re-run from the beginning' % seq)
            rewound = True
            resume_ok = False
            field._logfh.close()
            clean_field_dir(field)
            for d in (field.work, field.out, field.stepdir):
                os.makedirs(d, exist_ok=True)
            field._logfh = open(field.logfile, 'a', encoding='utf-8')
            return run_field_restart(field)
        before = snapshot_dir(field.dir)
        t0 = time.time()
        try:
            res, why = run_native_or_tool(field, rec)
        except StepFail as e:
            res, why = 'failed', str(e)
        except KeyError as e:
            res, why = 'failed', 'missing item %s' % e
        except Exception as e:                                  # noqa
            res, why = 'failed', '%s: %s' % (type(e).__name__, e)
        dt = time.time() - t0
        if res == 'skip':
            field.log('  SKIPPED: ' + why)
            entry.update(status='skipped', reason=why)
            counts['skipped'] += 1
            field.records.append(entry)
            continue
        if res == 'failed':
            field.log('  FAILED: ' + why)
            entry.update(status='failed', reason=why, seconds=round(dt, 3))
            counts['failed'] += 1
            field.records.append(entry)
            status, fail_step, fail_msg = 'failed', rec['step'], why
            break
        ca = rec.get('cat_after') or {}
        if field.replay and ca.get('crc') not in (None, '', '0'):
            cur = field.get_cat()
            ok_crc = bool(cur) and str(tcl_crc(cur)) == str(ca.get('crc'))
            entry['catalog_matches_gui'] = ok_crc
            if ok_crc:
                field.log('  catalog after step identical to the GUI session (crc32 %08x, %s rows x %s cols)'
                          % (tcl_crc(cur), ca.get('rows'), ca.get('cols')))
            else:
                field.log('  WARNING: catalog after this step differs from the GUI session '
                          '(GUI: %s rows x %s cols, crc %s; here: %d rows)'
                          % (ca.get('rows'), ca.get('cols'), ca.get('crc'),
                             sum(1 for l in cur.split('\n')[1:] if l.strip()) if cur else 0))
        after = snapshot_dir(field.dir)
        changed = sorted(p for p, v in after.items() if before.get(p) != v and not p.endswith('.tmp'))
        outs = []
        for p in changed:
            rel = os.path.relpath(p, field.dir)
            if rel in ('session.log', 'tool_stderr.log') or os.sep + '.steps' + os.sep in os.sep + rel:
                continue
            outs.append({'path': rel})
        entry.update(status='ok', seconds=round(dt, 3), outputs=outs, stdout_crc32=rec.get('_crc'),
                     stdout_matches_gui=rec.get('_crc_match'))
        field.log('  ok (%.1f s)' % dt)
        counts['ran'] += 1
        chain = key
        # step stamp for --resume
        for o in outs:
            pth = os.path.join(field.dir, o['path'])
        if os.path.exists(field.cat_path()):
            shutil.copyfile(field.cat_path(), os.path.join(sdir, '%04d.catalog.tsv' % seq))
        stamp = {'seq': seq, 'key': key, 'status': 'ok', 'seconds': round(dt, 3), 'outputs': outs,
                 'state': {k: v for k, v in field.state.items() if not k.startswith('_')},
                 'mask_stats': field.mask_stats}
        with open(sf, 'w') as f:
            json.dump(stamp, f)
        field.records.append(entry)
    return finish_field(field, status, fail_step, fail_msg, counts)


def run_field_restart(field):
    # called after a rewind: simply run again with resume disabled
    field._logfh.close()
    a2 = copy.copy(field.args)
    a2.resume = False
    f2 = Field(field.name, field.images, a2, field.cfg)
    f2.det_path = None
    return run_field(f2)


def finish_field(field, status, fail_step, fail_msg, counts):
    a = field.args
    cat = field.get_cat()
    nrows = ncols = 0
    if cat:
        lines = cat.split('\n')
        ncols = len(lines[0].split('\t'))
        nrows = sum(1 for l in lines[1:] if l.strip())
        write_text(os.path.join(field.dir, 'catalog_final.tsv'), cat)
    outputs = []
    for dp, dn, fn in os.walk(field.dir):
        dn[:] = [d for d in dn if d != '.steps']
        for f in sorted(fn):
            p = os.path.join(dp, f)
            rel = os.path.relpath(p, field.dir)
            if rel in ('manifest.json',) or f.endswith('.tmp'):
                continue
            ent = {'path': rel, 'size': os.path.getsize(p)}
            volatile = ('.undo' + os.sep in rel or '.redo' + os.sep in rel or f.endswith('.log') or f.endswith('.provenance.json')
                        or rel.startswith('work' + os.sep + 'edit_'))
            if volatile:
                ent['volatile'] = True
            else:
                ent['sha256'] = sha256_file(p)
                if re.search(r'\.fits?$', f, re.I):
                    ent['data_sha256'] = fits_data_sha256(p)
            outputs.append(ent)
    man = build_manifest(field, status, fail_step, fail_msg, counts, outputs, nrows, ncols)
    with open(os.path.join(field.dir, 'manifest.json'), 'w') as f:
        json.dump(man, f, indent=1, sort_keys=False)
    field.log('')
    field.log('field %s: %s   catalog %d rows x %d cols   steps ran=%d cached=%d skipped=%d failed=%d   %.1f s'
              % (field.name, status.upper(), nrows, ncols, counts['ran'], counts['cached'], counts['skipped'],
                 counts['failed'], time.time() - field.t_start))
    field.log('manifest: ' + os.path.join(field.dir, 'manifest.json'))
    if field._logfh:
        field._logfh.close()
    return {'field': field.name, 'status': status, 'objects': nrows, 'columns': ncols,
            'masked_fraction': field.mask_stats.get('FRACTION', ''), 'n_masked': field.mask_stats.get('N_MASKED', ''),
            'seconds': round(time.time() - field.t_start, 1), 'failed_step': fail_step, 'message': fail_msg,
            'steps_ran': counts['ran'], 'steps_cached': counts['cached'], 'steps_skipped': counts['skipped'],
            'dir': field.dir}


# ------------------------------------------------------------------ manifest
def tool_versions(args):
    root = args.ogfinder_root
    v = {'script_version': SCRIPT_VERSION, 'driver_python': sys.version.split()[0], 'platform': platform.platform()}
    try:
        code = ("import sys,importlib\nout={'python':sys.version.split()[0]}\n"
                "for m in ('numpy','scipy','astropy','sep','torch','sklearn','photutils','reproject'):\n"
                "    try:\n        out[m]=importlib.import_module(m).__version__\n    except Exception:\n        pass\n"
                "import json;print(json.dumps(out))")
        r = subprocess.run([args.python, '-c', code], capture_output=True, text=True, timeout=120)
        v['ogfinder_python'] = json.loads(r.stdout.strip().splitlines()[-1])
        v['ogfinder_python_exe'] = args.python
    except Exception as e:
        v['ogfinder_python_error'] = str(e)
    sx = os.path.join(root, 'ogfmeas', 'sextract.py')
    if os.path.isfile(sx):
        v['ogfmeas_sextract'] = {'path': sx, 'sha256': sha256_file(sx), 'size': os.path.getsize(sx)}
    sb = os.path.join(root, 'bin', 'ds9_sextract')
    if os.path.exists(sb):
        v['ds9_sextract'] = {'path': sb, 'sha256': sha256_file(sb), 'size': os.path.getsize(sb)}
        src = os.path.join(root, 'ds9', 'library', 'ds9_sextract.c')
        try:
            v['ds9_sextract']['source_git_blob'] = subprocess.run(['git', '-C', root, 'hash-object', src],
                                                                   capture_output=True, text=True).stdout.strip()
        except Exception:
            pass
    d9 = os.path.join(root, 'bin', 'ds9')
    if os.path.exists(d9):
        v['ds9'] = {'path': d9, 'sha256': sha256_file(d9), 'size': os.path.getsize(d9)}
    try:
        r = subprocess.run(['git', '-C', root, 'rev-parse', 'HEAD'], capture_output=True, text=True)
        v['ogfinder_git_head'] = r.stdout.strip()
        r = subprocess.run(['git', '-C', root, 'status', '--porcelain', '-uno'], capture_output=True, text=True)
        v['ogfinder_git_dirty_files'] = len([l for l in r.stdout.splitlines() if l.strip()])
    except Exception:
        pass
    v['recorded_in_gui_session'] = {k: SESSION_META.get(k) for k in ('git_head', 'git_dirty_sources', 'ds9_version',
                                                                      'ds9_exe', 'exported', 'session_started')}
    for lib in ('bin', 'ds9/library'):
        pass
    return v


def build_manifest(field, status, fail_step, fail_msg, counts, outputs, nrows, ncols):
    a = field.args
    ins = []
    for k, p in field.images.items():
        info = field.info_for(p)
        ins.append({'key': k, 'path': p, 'size': os.path.getsize(p) if os.path.exists(p) else None,
                    'sha256': file_digest_cached(p) if os.path.exists(p) else None,
                    'data_sha256': fits_data_sha256(p) if os.path.exists(p) and p.endswith('.fits') else None,
                    'header': {k2: info.get(k2) for k2 in ('FILTER', 'ZP_AB', 'PIXSCALE', 'PIVOT', 'NAXIS1', 'NAXIS2', 'INSTRUME') if k2 in info}})
    return {
        'field': field.name, 'status': status, 'failed_step': fail_step, 'message': fail_msg,
        'mode': a.mode, 'include_manual': bool(a.include_manual),
        'argv': sys.argv, 'cwd': os.getcwd(), 'finished': time.strftime('%Y-%m-%dT%H:%M:%S%z'),
        'inputs': ins,
        'parameters': {'detection_band': field.detect, 'registry': field.registry, 'bands_order': field.reg_order,
                       'overrides': a.override_list, 'cli_zp': a.zp_map, 'cli_pixel_scale': a.pixel_scale_map,
                       'field_config': field.cfg, 'python': a.python, 'ogfinder_root': a.ogfinder_root},
        'tools': tool_versions(a),
        'steps': field.records,
        'step_counts': counts,
        'catalog': {'rows': nrows, 'columns': ncols,
                    'sha256': hashlib.sha256(field.get_cat().encode('utf-8')).hexdigest() if field.get_cat() else None},
        'mask_stats': field.mask_stats,
        'outputs': outputs,
        'total_seconds': round(time.time() - field.t_start, 1),
    }


# ------------------------------------------------------------------ CLI
def parse_field_spec(spec):
    """NAME:band=path,band=path | NAME:path | NAME:path1,path2"""
    if ':' not in spec:
        raise argparse.ArgumentTypeError('--field expects NAME:band=path,band=path')
    name, rest = spec.split(':', 1)
    return name, rest


def images_from_items(items, root):
    """items: list of 'name=path' or 'path' -> ordered dict name->path (names from FITS FILTER when absent)"""
    out = {}
    for it in items:
        if '=' in it and not os.path.exists(it):
            k, p = it.split('=', 1)
            k = sanitize(k)
        else:
            p, k = it, None
        p = os.path.abspath(os.path.expanduser(p))
        if not os.path.exists(p):
            raise SystemExit('ERROR: input file not found: %s' % p)
        if k is None:
            info = sextract_info(root, p)
            k = sanitize(info.get('FILTER') or '') or None
            if k is None:
                k = sanitize(os.path.splitext(os.path.basename(p))[0])
            if len(items) == 1:
                k = None
        if k is None:
            k = '__single__'
        base = k
        n = 2
        while k in out:
            k = '%s_%d' % (base, n)
            n += 1
        out[k] = p
    return out


def collect_fields(args):
    fields = []        # (name, images dict, cfg)
    root = args.ogfinder_root
    cfg_all = {}
    if args.config:
        with open(args.config) as f:
            cfg_all = json.load(f)
        for k, v in (cfg_all.get('options') or {}).items():
            if getattr(args, k.replace('-', '_'), None) in (None, False, [], {}):
                setattr(args, k.replace('-', '_'), v)
        for name, fc in (cfg_all.get('fields') or {}).items():
            bands = fc.get('bands') or {}
            if isinstance(bands, list):
                imgs = images_from_items(bands, root)
            else:
                imgs = {sanitize(k): os.path.abspath(os.path.expanduser(v)) for k, v in bands.items()}
            if fc.get('image'):
                imgs = {'__single__': os.path.abspath(os.path.expanduser(fc['image']))}
            fields.append((name, imgs, fc))
    if args.bands:
        imgs = images_from_items(args.bands, root)
        fields.append((args.field_name or sanitize(os.path.splitext(os.path.basename(list(imgs.values())[0]))[0]),
                       imgs, {}))
    if args.images:
        its = args.images
        if args.data_dir:
            its = [os.path.join(args.data_dir, i) if not os.path.isabs(i) and not os.path.exists(i) else i for i in its]
        imgs = images_from_items(its, root)
        fields.append((args.field_name or sanitize(os.path.splitext(os.path.basename(list(imgs.values())[0]))[0]),
                       imgs, {}))
    for spec in args.field or []:
        name, rest = parse_field_spec(spec)
        imgs = images_from_items([s for s in rest.split(',') if s], root)
        fields.append((sanitize(name), imgs, {}))
    if args.input_list:
        for ln in open(args.input_list):
            ln = ln.split('#')[0].strip()
            if not ln:
                continue
            tok = ln.split()
            if len(tok) >= 2 and '=' not in tok[0] and not os.path.exists(tok[0]):
                name, items = sanitize(tok[0]), tok[1:]
            else:
                items = tok
                name = sanitize(os.path.splitext(os.path.basename(items[0].split('=')[-1]))[0])
            fields.append((name, images_from_items(items, root), {}))
    if args.data_dir and not args.images and not args.bands and not args.field and not args.input_list:
        fits = sorted(glob.glob(os.path.join(args.data_dir, '*.fits')) + glob.glob(os.path.join(args.data_dir, '*.fit')))
        rec_bases = {os.path.basename(i['path']): i['key'] for i in IMAGES}
        have = [f for f in fits if os.path.basename(f) in rec_bases]
        if have and args.mode == 'replay':
            imgs = {rec_bases[os.path.basename(f)]: os.path.abspath(f) for f in have}
        else:
            imgs = images_from_items(fits, root)
        fields.append((args.field_name or sanitize(os.path.basename(os.path.abspath(args.data_dir))), imgs, {}))
    return fields


def normalize_images(args, name, imgs):
    """replay: map files to the band keys of the GUI session (by key, else by basename).
    pipeline: keep the user's names; an unnamed single image is named after its FITS FILTER
    keyword (or file name) -- never after the band of the recorded session."""
    rec_by_base = {os.path.basename(i['path']): i['key'] for i in IMAGES}
    rec_keys = [i['key'] for i in IMAGES]
    det_rec = SESSION_META.get('detection_key') or (rec_keys[0] if rec_keys else 'main')
    out = {}
    for k, p in imgs.items():
        if args.mode == 'replay':
            if k == '__single__':
                k = rec_by_base.get(os.path.basename(p), det_rec)
            elif k not in rec_keys and os.path.basename(p) in rec_by_base:
                k = rec_by_base[os.path.basename(p)]
        elif k == '__single__':
            info = sextract_info(args.ogfinder_root, p)
            k = sanitize(info.get('FILTER') or '') or sanitize(os.path.splitext(os.path.basename(p))[0])
            if k == det_rec and False:
                pass
        out[k] = p
    return out


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('images', nargs='*', help='input FITS image(s) of ONE field; several = bands '
                    '(band name from the FITS FILTER keyword, or NAME=path)')
    ap.add_argument('--bands', nargs='+', metavar='NAME=PATH', help='bands of one field, e.g. F105W=a.fits F160W=b.fits')
    ap.add_argument('--detection-band', help='band (name) used for detection / masks / ICL; default: the recorded one if '
                    'present, else the first band')
    ap.add_argument('--data-dir', help='directory with input FITS files (replay: files named as in the GUI session; '
                    'pipeline: every *.fits is a band of one field)')
    ap.add_argument('--field', action='append', metavar='NAME:band=path,band=path',
                    help='a field (repeatable): NAME:F105W=a.fits,F160W=b.fits  or NAME:path')
    ap.add_argument('--field-name', help='name of the single field given by positional images / --bands')
    ap.add_argument('--input-list', help='text file, one field per line: "NAME path1 [path2 ...]" or "NAME band=path ..."')
    ap.add_argument('--config', help='JSON config: {"options": {...}, "fields": {NAME: {"bands": {"F160W": path}, '
                    '"detection_band": .., "zp": {..}, "pixel_scale": {..}, "fwhm": {..}, "overrides": [[step_glob, flag, value]]}}}')
    ap.add_argument('--outdir', required=True, help='output directory (one sub-directory per field)')
    ap.add_argument('--python', default=sys.executable,
                    help='python interpreter for the OGFinder python steps (needs numpy/scipy/astropy/sep). '
                         'default: this interpreter')
    ap.add_argument('--ogfinder-root', default=OGFINDER_ROOT_RECORDED,
                    help='OGFinder install root (default: recorded at export time: %s)' % OGFINDER_ROOT_RECORDED)
    ap.add_argument('--mode', choices=['pipeline', 'replay'], default='pipeline')
    ap.add_argument('--include-manual', action='store_true',
                    help='pipeline mode: also run the steps that were done by hand in the GUI')
    ap.add_argument('--trim', action='append', default=[], metavar='COL=MIN:MAX',
                    help='pipeline mode: replace the limits of the recorded catalog trim/filter steps '
                         '(either bound may be empty), e.g. --trim MAG_AUTO=18:27')
    ap.add_argument('--allow-network', action='store_true', help='run steps that need network access (cross-match, external AI services)')
    ap.add_argument('--allow-agent-images', action='store_true', help='with --allow-agent-cli: also run agent-CLI steps that were recorded with "send image cutouts" ticked')
    ap.add_argument('--allow-agent-cli', action='store_true', help='run ai.run steps that use an agent CLI (Codex CLI, Claude Code, agy/Gemini CLI, Grok): the CLI forwards catalogue rows to its provider\'s cloud model')
    ap.add_argument('--jobs', type=int, default=1, help='fields processed in parallel')
    ap.add_argument('--resume', action='store_true', help='skip steps whose inputs/parameters are unchanged')
    ap.add_argument('--zp', action='append', default=[], metavar='[BAND=]ZP', help='AB zeropoint override')
    ap.add_argument('--pixel-scale', action='append', default=[], metavar='[BAND=]ARCSEC', help='pixel scale override')
    ap.add_argument('--fwhm', action='append', default=[], metavar='[BAND=]ARCSEC', help='PSF FWHM (arcsec) per band')
    ap.add_argument('--override', action='append', default=[], metavar='STEP:--flag=VALUE',
                    help='override a command-line flag of the recorded steps whose name matches STEP (glob), '
                         'e.g. extract:--detect-thresh=2.0 or "*:--n-workers=4"')
    ap.add_argument('--list-steps', action='store_true', help='print the recorded steps and exit')
    ap.add_argument('--dry-run', action='store_true', help='resolve inputs and print the plan, run nothing')
    args = ap.parse_args(argv)

    if args.list_steps:
        for r in STEPS:
            print('%3s %-8s %-24s %s' % (r['seq'], r['class'].upper(), r['step'], r['title']))
        return 0
    args.ogfinder_root = os.path.abspath(args.ogfinder_root)
    args.outdir = os.path.abspath(args.outdir)
    if not os.path.isdir(os.path.join(args.ogfinder_root, 'ds9', 'library')):
        print('ERROR: OGFinder root %s has no ds9/library (use --ogfinder-root)' % args.ogfinder_root, file=sys.stderr)
        return 2
    for t in ('ds9_catalog_edit.py', 'ds9_mask.py'):
        if not os.path.exists(os.path.join(args.ogfinder_root, 'ds9', 'library', t)):
            print('ERROR: %s missing in %s/ds9/library' % (t, args.ogfinder_root), file=sys.stderr)
            return 2
    if not os.path.exists(os.path.join(args.ogfinder_root, 'ogfmeas', 'sextract.py')) and any(
            r['tool'] == 'sextract' for r in STEPS):
        print('WARNING: %s/ogfmeas/sextract.py not found' % args.ogfinder_root, file=sys.stderr)

    def numeric_map(items, label):
        m = {}
        for it in items:
            if '=' in it:
                k, v = it.split('=', 1)
                m[sanitize(k)] = v
            else:
                m['*'] = it
        return m
    args.zp_map = numeric_map(args.zp, 'zp')
    args.pixel_scale_map = numeric_map(args.pixel_scale, 'pixel-scale')
    args.fwhm_map = numeric_map(args.fwhm, 'fwhm')
    ov = []
    for o in args.override:
        m = re.match(r'^([^:]+):(--[A-Za-z0-9-]+)=(.*)$', o)
        if not m:
            ap.error('bad --override %r' % o)
        ov.append((m.group(1), m.group(2), m.group(3)))
    args.override_list = ov
    args.trim_map = {}
    for t in args.trim:
        m = re.match(r'^([^=]+)=([^:]*):(.*)$', t)
        if not m:
            ap.error('bad --trim %r (expected COL=MIN:MAX)' % t)
        args.trim_map[m.group(1)] = (m.group(2), m.group(3))

    fields = collect_fields(args)
    if not fields:
        ap.error('no input: give FITS images, --bands, --field, --input-list, --data-dir or --config')
    names = [f[0] for f in fields]
    if len(set(names)) != len(names):
        ap.error('duplicate field names: %s' % names)
    os.makedirs(args.outdir, exist_ok=True)
    objs = []
    for name, imgs, cfg in fields:
        objs.append(Field(name, normalize_images(args, name, imgs), args, cfg))
    # plan
    n_auto = sum(1 for r in STEPS if r['class'] == 'auto')
    n_man = sum(1 for r in STEPS if r['class'] == 'manual')
    say('', 'OGFinder session script: %d recorded steps (%d automatic, %d manual), mode=%s%s, %d field(s), jobs=%d'
        % (len(STEPS), n_auto, n_man, args.mode, '+manual' if args.include_manual else '', len(objs), args.jobs))
    if args.dry_run:
        for f in objs:
            say(f.name, 'images: %s' % f.images)
        return 0
    t0 = time.time()
    results = []

    def work(f):
        try:
            return run_field(f)
        except Exception as e:                                   # noqa
            say(f.name, 'FATAL: %s: %s' % (type(e).__name__, e))
            return {'field': f.name, 'status': 'failed', 'objects': 0, 'columns': 0, 'masked_fraction': '',
                    'n_masked': '', 'seconds': round(time.time() - f.t_start, 1), 'failed_step': 'setup',
                    'message': str(e), 'steps_ran': 0, 'steps_cached': 0, 'steps_skipped': 0, 'dir': f.dir}
    if args.jobs > 1 and len(objs) > 1:
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.jobs) as ex:
            results = list(ex.map(work, objs))
    else:
        results = [work(f) for f in objs]
    cols = ['field', 'status', 'objects', 'columns', 'masked_fraction', 'n_masked', 'steps_ran', 'steps_cached',
            'steps_skipped', 'seconds', 'failed_step', 'message']
    lines = ['\t'.join(cols)] + ['\t'.join(str(r.get(c, '')) for c in cols) for r in results]
    write_text(os.path.join(args.outdir, 'summary.tsv'), '\n'.join(lines) + '\n')
    with open(os.path.join(args.outdir, 'summary.json'), 'w') as f:
        json.dump({'mode': args.mode, 'total_seconds': round(time.time() - t0, 1), 'fields': results}, f, indent=1)
    say('', '')
    say('', 'SUMMARY  (%s)' % os.path.join(args.outdir, 'summary.tsv'))
    for l in lines:
        say('', l.replace('\t', ' | '))
    nfail = sum(1 for r in results if r['status'] != 'ok')
    say('', '%d field(s) ok, %d failed, %.1f s total' % (len(results) - nfail, nfail, time.time() - t0))
    return 1 if nfail else 0


if __name__ == '__main__':
    sys.exit(main())
